  'BIOMD0000000004': { title: 'A minimal cascade model for the mitotic oscillator involving cyclin and cdc2 kinase.', authors: ['A Goldbeter'], journal: 'Proceedings of the National Academy of Sciences of the United States of America', year: '1991', volume: '88', issue: '20', pages: '9107-9111', pubmedId: '1833774', link: 'http://identifiers.org/pubmed/1833774', description: 'This model represents the inactive forms of CDC-2 Kinase and Cyclin Protease as separate species, unlike the ODEs in the published paper, in which the equations for the inactive forms are substituted into the equations for the active forms using a mass conservation rule M+MI=1,X+XI=1. Mass is still conserved in this model through the explicit reactions M&lt;-&gt;MI and X&lt;-&gt;XI. The terms in the kinetic laws are identical to the corresponding terms in the kinetic laws in the published paper.' },
