  'BIOMD0000000540': { title: 'Reconstruction of insulin signal flow from phosphoproteome and metabolome data.', authors: ['Katsuyuki Yugi', 'Hiroyuki Kubota', 'Yu Toyoshima', 'Rei Noguchi', 'Kentaro Kawata', 'Yasunori Komori', 'Shinsuke Uda', 'Katsuyuki Kunida', 'Yoko Tomizawa', 'Yosuke Funato', 'Hiroaki Miki', 'Masaki Matsumoto', 'Keiichi I Nakayama', 'Kasumi Kashikura', 'Keiko Endo', 'Kazutaka Ikeda', 'Tomoyoshi Soga', 'Shinya Kuroda'], journal: 'Cell reports', year: '2014', volume: '8', issue: '4', pages: '1171-1183', pubmedId: '25131207', link: 'http://identifiers.org/pubmed/25131207', description: 'Insulin induces phosphorylation and activation of liver-type phosphofructokinase 1, which thereby controls a key reaction in glycolysis. This mechanism is revealed using the mathematical model. In this model, the PFKL phosphorylation time courses are obtained from experimental data.' },
  'BIOMD0000000541': { title: 'Reconstruction of insulin signal flow from phosphoproteome and metabolome data.', authors: ['Katsuyuki Yugi', 'Hiroyuki Kubota', 'Yu Toyoshima', 'Rei Noguchi', 'Kentaro Kawata', 'Yasunori Komori', 'Shinsuke Uda', 'Katsuyuki Kunida', 'Yoko Tomizawa', 'Yosuke Funato', 'Hiroaki Miki', 'Masaki Matsumoto', 'Keiichi I Nakayama', 'Kasumi Kashikura', 'Keiko Endo', 'Kazutaka Ikeda', 'Tomoyoshi Soga', 'Shinya Kuroda'], journal: 'Cell reports', year: '2014', volume: '8', issue: '4', pages: '1171-1183', pubmedId: '25131207', link: 'http://identifiers.org/pubmed/25131207', description: 'Insulin induces phosphorylation and activation of liver-type phosphofructokinase 1, which thereby controls a key reaction in glycolysis. This mechanism is revealed using the mathematical model. In this model, the PFKL phosphorylation time courses are calculation from the signalling pathway model developed by Kubata et al. (2012) ( MODEL1204060000 - Kubota2012_InsulinAction_AKTpathway).' },
