  'MODEL1304300000': { title: 'Co-response analysis: a new experimental strategy for metabolic control analysis.', authors: ['J H Hofmeyr', 'Athel Cornish-Bowden'], journal: 'Journal of theoretical biology', year: '1996', volume: '182', issue: '3', pages: '371-380', pubmedId: '8944170', link: 'http://identifiers.org/pubmed/8944170', description: 'Understanding of genetic mechanisms would not be possible by studying the properties of individual components. To better understand the system as a whole, it is necessary to study the interaction between components and their response to each other. This paper describes a strategy for the experimental control analysis called co-response analysis.' },
