  'BIOMD0000000448': { title: 'Insulin signaling in type 2 diabetes: experimental and modeling analyses reveal mechanisms of insulin resistance in human adipocytes.', authors: ['Cecilia Brännmark', 'Elin Nyman', 'Siri Fagerholm', 'Linnéa Bergenholm', 'Eva-Maria Ekstrand', 'Gunnar Cedersund', 'Peter Strålfors'], journal: 'The Journal of biological chemistry', year: '2013', volume: '288', issue: '14', pages: '9867-9880', pubmedId: '23400783', link: 'http://identifiers.org/pubmed/23400783', description: 'The paper describes insulin signalling in human adipocytes under normal and diabetic states using mathematical models based on experimental data. This model corresponds to insulin signalling under normal condtion' },
